def find_zero(xs: list):
    if poly(xs, 0.0) == 0:
        return 0.0

    lo = -1.0
    hi = 1.0
    if poly(xs, lo) == 0:
        return lo
    if poly(xs, hi) == 0:
        return hi

    while poly(xs, lo) * poly(xs, hi) > 0:
        lo *= 2.0
        hi *= 2.0
        if abs(hi) > 1e100:
            break

    for _ in range(200):
        mid = (lo + hi) * 0.5
        val = poly(xs, mid)
        if val == 0:
            return mid
        if poly(xs, lo) * val <= 0:
            hi = mid
        else:
            lo = mid
    return (lo + hi) * 0.5
